mapper.select:
SELECT count(*) FROM ovie_web.denue  d, ovie_web.areas a
	WHERE  a.gid=#{id}
	AND ST_Intersects(a.the_geom,d.the_geom)

SELECT COUNT(*), d.desc_cort FROM ovie_web.denue d,ovie_web.areas a
WHERE ST_Intersects(a.the_geom,d.the_geom)
AND cve_scian::numeric=#{cve}
AND a.gid=#{id}
GROUP BY d.desc_cort
